	public function DoExecute($oTrigger, $aContextArgs)
	{
		$aRecipientsIds = [];
		$oPotentialRecipientsSearch = DBObjectSearch::FromOQL($this->Get('recipients'));
		$oPotentialRecipientsSearch->AllowAllData();
		$oPotentialRecipientsSet = new DBObjectSet($oPotentialRecipientsSearch, array(), $aContextArgs);

		$bIsAsync = $this->IsAsynchronous();
		[$sPreviousLanguage, $aPreviousPluginProperties] = $this->SetNotificationLanguage();

		$sMessage = MetaModel::ApplyParams($this->Get('message'), $aContextArgs);
		$sTitle = MetaModel::ApplyParams($this->Get('title'), $aContextArgs);
		$sUrl = MetaModel::ApplyParams($this->Get('url'), $aContextArgs);
    $iObjectId = 0;
    $sObjectClass = null;
		if (array_key_exists('this->object()', $aContextArgs)) {
				$iObjectId = $aContextArgs['this->object()']->GetKey();
				$sObjectClass = get_class($aContextArgs['this->object()']);
    }

    if ($this->IsBeingTested()) {
      // If action is being tested, send notification to the test recipient only, no matter what (unsubscribed, disabled, no access to the backoffice, ...)
      $iTestRecipientId = $this->Get('test_recipient_id');
      if ($iTestRecipientId > 0) {
        $aRecipientsIds[] = $iTestRecipientId;
      }
    } else {
      // Otherwise, find the recipients to which we can actually send the notification among all the potential ones
      while ($oPotentialRecipient = $oPotentialRecipientsSet->Fetch()) {
        // Skip recipients that have no users
        if ($oPotentialRecipient instanceof Person && UserRights::GetUserFromPerson($oPotentialRecipient, false) === null) {
          continue;
        }

        // Skip potential recipient that have no user with access to the backoffice
        $oPotentialRecipientUsersSearch = DBObjectSearch::FromOQL("SELECT User WHERE contactid = " . $oPotentialRecipient->GetKey() . " AND status = 'enabled'");
        $oPotentialRecipientUsersSearch->AllowAllData();
        $oPotentialRecipientUsersSet = new DBObjectSet($oPotentialRecipientUsersSearch);
        $oPortalDispatcher = new PortalDispatcher('backoffice');
        // - Check if the user has access to the backoffice
        $bHasAccessToBackoffice = false;
        while ($oPotentialRecipientUser = $oPotentialRecipientUsersSet->Fetch()) {
          // Skip potential recipients with user that don't have access to the backoffice
          if (false === $oPortalDispatcher->IsUserAllowed($oPotentialRecipientUser)) {
                    continue;
          }

          $bHasAccessToBackoffice = true;
          break;
        }
        // - Skip it if necessary
        if (false === $bHasAccessToBackoffice) {
          continue;
        }

        // Skip potential recipients that have unsubscribed
        if (!\Combodo\iTop\Service\Notification\NotificationsService::GetInstance()->IsSubscribed($oTrigger, $this, $oPotentialRecipient)) {
          continue;
        }

        $aRecipientsIds[] = $oPotentialRecipient->GetKey();

        // Register subscription even though the notification is not sent yet
        \Combodo\iTop\Service\Notification\NotificationsService::GetInstance()->RegisterSubscription($oTrigger, $this, $oPotentialRecipient);
      }
    }

		try {
			if ($bIsAsync === true) {
				AsyncSendNewsroom::AddToQueue($this->GetKey(), $oTrigger->GetKey(), $aRecipientsIds, $sMessage, $sTitle, $sUrl, $iObjectId, $sObjectClass);
			} else {
				foreach ($aRecipientsIds as $iRecipientId) {
					$oEvent = Combodo\iTop\Service\Notification\Event\EventNotificationNewsroomService::MakeEventFromAction($this, $iRecipientId, $oTrigger->GetKey(), $sMessage, $sTitle, $sUrl, $iObjectId, $sObjectClass);
					$oEvent->DBInsertNoReload();
				}
			}
		} catch (CoreCannotSaveObjectException $e) {
			ExceptionLog::LogException($e);
			foreach($aRecipientsIds as $iRecipientId) {
				$oEvent = Combodo\iTop\Service\Notification\Event\EventNotificationNewsroomService::MakeEventFromAction($this,
					$iRecipientId,
					$oTrigger->GetKey(),
					Dict::S('Core:EventNotificationNewsroom:ErrorOnDBInsert'),
					Dict::S('Core:EventNotificationNewsroom:ErrorNotificationNotSent'),
					$sUrl,
					$iObjectId,
					$sObjectClass
				);
				$oEvent->DBInsertNoReload();
			}
		}

		$this->SetNotificationLanguage($sPreviousLanguage, $aPreviousPluginProperties['language_code'] ?? null);
	}

public static function GetAsynchronousGlobalSetting(): bool
{
	return utils::GetConfig()->Get('notifications.itop.send_asynchronously');
}

public function CheckCredentials($sPassword)
{
	$sServer = $this->Get('ldap_server');
	if (empty($sServer))
	{
		$sURI = MetaModel::GetModuleSetting('authent-ldap', 'uri', 'ldap://localhost');

		$sDefaultLDAPUser = MetaModel::GetModuleSetting('authent-ldap', 'default_user', '');
		$sDefaultLDAPPwd = MetaModel::GetModuleSetting('authent-ldap', 'default_pwd', '');
		$bLDAPStartTLS = MetaModel::GetModuleSetting('authent-ldap', 'start_tls', false);

		$aOptions = MetaModel::GetModuleSetting('authent-ldap', 'options', array());
		$sLDAPUserQuery = MetaModel::GetModuleSetting('authent-ldap', 'user_query', '');
		$sBaseDN = MetaModel::GetModuleSetting('authent-ldap', 'base_dn', '');
		$bDebug = MetaModel::GetModuleSetting('authent-ldap', 'debug', false);
	}
	else
	{
		$aServers = MetaModel::GetModuleSetting('authent-ldap', 'servers', array());
		if (!array_key_exists($sServer, $aServers))
		{
			$bDebug = MetaModel::GetModuleSetting('authent-ldap', 'debug', false);
			$this->LogIssue($bDebug, "ldap_authentication: bad LDAP server configuration: '$sServer' not found");
			return false;
		}
		$aServerParams = $aServers[$sServer];
		$sURI = $aServerParams['uri'] ?? 'ldap://localhost';
		$sDefaultLDAPUser = isset($aServerParams['default_user']) ? $aServerParams['default_user'] : '';
		$sDefaultLDAPPwd = isset($aServerParams['default_pwd']) ? $aServerParams['default_pwd'] : '';
		$bLDAPStartTLS = isset($aServerParams['start_tls']) ? $aServerParams['start_tls'] : false;
		$aOptions = isset($aServerParams['options']) ? $aServerParams['options'] : array();
		$sLDAPUserQuery = isset($aServerParams['user_query']) ? $aServerParams['user_query'] : '';
		$sBaseDN = isset($aServerParams['base_dn']) ? $aServerParams['base_dn'] : '';
		$bDebug = isset($aServerParams['debug']) ? $aServerParams['debug'] : false;
	}

	$hDS = @ldap_connect($sURI);
	if ($hDS === false)
	{
		$this->LogIssue($bDebug, "ldap_authentication: can not connect to the LDAP server '$sURI'. Check the configuration file config-itop.php.");
		return false;
	}
	if (array_key_exists(LDAP_OPT_DEBUG_LEVEL, $aOptions))
	{
		// Set debug level before trying to connect, so that debug info appear in the PHP error log if ldap_connect goes wrong
		$bRet = ldap_set_option($hDS, LDAP_OPT_DEBUG_LEVEL, $aOptions[LDAP_OPT_DEBUG_LEVEL]);
		$this->LogInfo($bDebug, "ldap_set_option('LDAP_OPT_DEBUG_LEVEL', '{$aOptions[LDAP_OPT_DEBUG_LEVEL]}') returned ".($bRet ? 'true' : 'false'));
	}
	foreach($aOptions as $name => $value)
	{
		$bRet = ldap_set_option($hDS, $name, $value);
		$this->LogInfo($bDebug, "ldap_set_option('$name', '$value') returned ".($bRet ? 'true' : 'false'));
	}
	if ($bLDAPStartTLS)
	{
		$this->LogInfo($bDebug, "ldap_authentication: start tls required.");
		$hStartTLS = ldap_start_tls($hDS);
		//$this->LogIssue($bDebug, "ldap_authentication: hStartTLS = '$hStartTLS'");
		if (!$hStartTLS)
		{
			$this->LogIssue($bDebug, "ldap_authentication: start tls failed.");
			return false;
		}
	}

	if ($bind = @ldap_bind($hDS, $sDefaultLDAPUser, $sDefaultLDAPPwd))
	{
		// Search for the person, using the specified query expression
		$sLogin = $this->Get('login');
		$iContactId = $this->Get('contactid');
		$sFirstName = '';
		$sLastName = '';
		$sEMail = '';
		if ($iContactId > 0)
		{
			$oPerson = MetaModel::GetObject('Person', $iContactId);
			if (is_object($oPerson))
			{
				$sFirstName = $oPerson->Get('first_name');
				$sLastName = $oPerson->Get('name');
				$sEMail = $oPerson->Get('email');
			}
		}
		// %1$s => login
		// %2$s => first name
		// %3$s => last name
		// %4$s => email
		$sQuery = sprintf($sLDAPUserQuery, $sLogin, $sFirstName, $sLastName, $sEMail);
		$hSearchResult = @ldap_search($hDS, $sBaseDN, $sQuery);

		$iCountEntries = ($hSearchResult !== false) ? @ldap_count_entries($hDS, $hSearchResult) : 0;
		switch($iCountEntries)
		{
			case 1:
			// Exactly one entry found, let's check the password by trying to bind with this user
			$aEntry = @ldap_get_entries($hDS, $hSearchResult);
			$sUserDN = $aEntry[0]['dn'];
			$bUserBind =  @ldap_bind($hDS, $sUserDN, $sPassword);
			if (($bUserBind !== false) && !empty($sPassword))
			{
				@ldap_unbind($hDS);
				return true; // Password Ok
			}
			$this->LogIssue($bDebug, "ldap_authentication: wrong password for user: '$sUserDN'.");
			return false; // Wrong password
			break;

			case 0:
			// User not found...
			$this->LogIssue($bDebug, "ldap_authentication: no entry found with the query '$sQuery', base_dn = '$sBaseDN'. User not found in LDAP.");
			break;

			default:
			// More than one entry... maybe the query is not specific enough...
			$this->LogIssue($bDebug, "ldap_authentication: several (".@ldap_count_entries($hDS, $hSearchResult).") entries match the query '$sQuery', base_dn = '$sBaseDN', check that the query defined in config-itop.php is specific enough.");
		}
		return false;
	}
	else
	{
		// Trace: invalid default user for LDAP initial binding
		$this->LogIssue($bDebug, "ldap_authentication: cannot bind to the LDAP server '$sURI', user='$sDefaultLDAPUser', pwd='****'. Error: '".ldap_error($hDS)."'. Check the configuration file config-itop.php.");
		return false;
	}
}

