protected function LogIssue($bDebug, $sMessage, $aData = array())
{
	if ($bDebug)
	{
		if (MetaModel::IsLogEnabledIssue() && MetaModel::IsValidClass('EventIssue'))
		{
			$oLog = new EventIssue();

			$oLog->Set('message', $sMessage);
			$oLog->Set('userinfo', '');
			$oLog->Set('issue', 'LDAP Authentication');
			$oLog->Set('impact', 'User login rejected');
			$oLog->Set('data', $aData);
			$oLog->DBInsertNoReload();
		}
	}
	IssueLog::Error($sMessage);
}

protected function LogInfo($bDebug, $sMessage)
{
	if ($bDebug)
	{
		IssueLog::Info($sMessage);
	}
}

public function DBInsertNoReload()
{
    $this->SetCurrentDateIfNull('creation_date');
    $iUserId = CMDBChange::GetCurrentUserId();
    if(utils::IsNotNullOrEmptyString($iUserId)){
           $this->SetIfNull('user_id', $iUserId);

          // Get Contact from user
          $oUser = MetaModel::GetObject('User', $iUserId, true, true);
          $this->SetIfNull('contact_id', $oUser->Get('contactid'));
     }
    return parent::DBInsertNoReload();
}

public static function MapContextParam($sContextParam)
{
	if ($sContextParam == 'org_id')
	{
		return 'item_org_id';
	}
	else
	{
		return null;
	}
}

	public function SetItem($oItem, $bUpdateOnChange = false)
	{
		$sClass = get_class($oItem);
		$iItemId = $oItem->GetKey();

 		$this->Set('item_class', $sClass);
 		$this->Set('item_id', $iItemId);

		$aCallSpec = array($sClass, 'MapContextParam');
		if (is_callable($aCallSpec))
		{
			$sAttCode = call_user_func($aCallSpec, 'org_id'); // Returns null when there is no mapping for this parameter					
			if (MetaModel::IsValidAttCode($sClass, $sAttCode))
			{
				$iOrgId = $oItem->Get($sAttCode);
				if ($iOrgId > 0)
				{
					if ($iOrgId != $this->Get('item_org_id'))
					{
						$this->Set('item_org_id', $iOrgId);
						if ($bUpdateOnChange)
						{
							$this->DBUpdate();
						}
					}
				}
			}
		}
	}

	public function SetDefaultOrgId()
	{
    // Check that the organization CAN be fetched from the current user
    //
    if (MetaModel::IsValidClass('Person'))
    {
      $aCallSpec = array('Person', 'MapContextParam');
      if (is_callable($aCallSpec))
      {
        $sAttCode = call_user_func($aCallSpec, 'org_id'); // Returns null when there is no mapping for this parameter
        if (MetaModel::IsValidAttCode('Person', $sAttCode))
        {
          // OK - try it
          //
          $oCurrentPerson = MetaModel::GetObject('Person', UserRights::GetContactId(), false);
          if ($oCurrentPerson)
          {
            $this->Set('item_org_id', $oCurrentPerson->Get($sAttCode));
          }
        }
      }
		}
	}

	public function CheckUsersOnUpdate(Combodo\iTop\Service\Events\EventData $oEventData)
	{
      // This method can block the Person modification, by adding a Check Issue
      $aChanges = $this->ListChanges();
      // Current User may not be allowed to see User class, so we can't use $this->Get('user_list')
      $oSearch = new DBObjectSearch('User');
      $oSearch->AddCondition('contactid', $this->GetKey(), '=');
      $oSearch->AllowAllData();
      $oUserSet = new DBObjectSet($oSearch);

      // Change was not made by a DataSynchro and the organization's person was changed and there are associated Users
      if (!ContextTag::Check(ContextTag::TAG_SYNCHRO) && array_key_exists('org_id', $aChanges) && ($oUserSet->Count() > 0)) {
          while($oUser = $oUserSet->Fetch())
          {
              $oAddon = UserRights::GetModuleInstance();
              $aOrgs = $oAddon->GetUserOrgs($oUser,'Organization');
              $oSet = $oUser->Get('profile_list');
              $aProfiles = $oSet->GetColumnAsArray('profile');

              // User is not allowed on the new Organization and has 'Portal user' Profile and is enabled
              if ((count($aOrgs) > 0) && !in_array($this->Get('org_id'), $aOrgs) &&  in_array('Portal user',$aProfiles) && ($oUser->Get('status') === 'enabled'))
              {   // Let's block the Person modification,
                  // replace by $this->AddCheckWarning(...) if you don't want to block the modification
                  $this->AddCheckIssue(Dict::Format('Class:Person/Error:ChangingOrgDenied', $this->Get('org_id_friendlyname')));
              }
          }
      }
	}

  	public function CheckToDelete(&$oDeletionPlan)
  	{
  		if (MetaModel::GetConfig()->Get('demo_mode'))
		{
			if ($this->HasUserAccount())
			{
				// Do not let users change user accounts in demo mode
				$oDeletionPlan->AddToDelete($this, null);
				$oDeletionPlan->SetDeletionIssues($this, array('deletion not allowed in demo mode.'), true);
				$oDeletionPlan->ComputeResults();
				return false;
			}
		}
		return parent::CheckToDelete($oDeletionPlan);
  	}

  	public function DBDeleteSingleObject()
	{
		if (MetaModel::GetConfig()->Get('demo_mode'))
		{
			if ($this->HasUserAccount())
			{
				// Do not let users change user accounts in demo mode
				return;
			}
		}
		parent::DBDeleteSingleObject();
	}

public function GetAttributeFlags($sAttCode, &$aReasons = array(), $sTargetState = '')
{
	if ( ($sAttCode == 'org_id') && (!$this->IsNew()) )
	{
		if (MetaModel::GetConfig()->Get('demo_mode'))
		{
			if ($this->HasUserAccount())
			{
				// Do not let users change user accounts in demo mode
				return OPT_ATT_READONLY;
			}
		}
	}
	return parent::GetAttributeFlags($sAttCode, $aReasons, $sTargetState);
}

  	public function HasUserAccount()
  	{
		static $bHasUserAccount = null;
		if (is_null($bHasUserAccount))
		{
			$oUserSet = new DBObjectSet(DBSearch::FromOQL('SELECT User WHERE contactid = :person', array('person' => $this->GetKey())));
			$bHasUserAccount = ($oUserSet->Count() > 0);
		}
		return $bHasUserAccount;
  	}

public function DisplayBareProperties(WebPage $oPage, $bEditMode = false, $sPrefix = '', $aExtraParams = array())
	{
		$aFieldsMap = parent::DisplayBareProperties($oPage, $bEditMode, $sPrefix, $aExtraParams);
		if (!$bEditMode)
		{
			$oPage->add('<fieldset>');
			$oPage->add('<legend>'.Dict::S('Class:Document:PreviewTab').'</legend>');
			$oPage->add($this->DisplayDocumentInline($oPage, 'file'));
			$oPage->add('</fieldset>');
		}
		return $aFieldsMap;
	}

public function OnLinksChangedTicket(Combodo\iTop\Service\Events\EventData $oEventData)
{
    $this->UpdateImpactedItems();
}

public function OnBeforeWriteTicket(Combodo\iTop\Service\Events\EventData $oEventData)
{
    // do not update impacted items from portal
    if(ContextTag::Check(ContextTag::TAG_PORTAL)){
        return;
    }
    $aChanges = $this->ListChanges();
    if ($this->IsNew() || array_key_exists('functionalcis_list', $aChanges) || array_key_exists('contacts_list', $aChanges)) {
        $this->UpdateImpactedItems();
    }
}

public function DBInsertNoReload()
{
      $iNextId = ItopCounter::IncClass(get_class($this));
      $sRef = $this->MakeTicketRef($iNextId);
      $this->SetIfNull('ref', $sRef);
      $iKey = parent::DBInsertNoReload();
      return $iKey;
}

protected function MakeTicketRef($iNextId)
{
        return sprintf(static::GetTicketRefFormat(), $iNextId);
}

public static function GetTicketRefFormat()
{
        return 'T-%06d';
}

	public function AddCurrentUserToContacts()
    {
        $iPersonId = UserRights::GetContactId();
        if ($iPersonId > 0) {
            $oContactsSet = $this->Get('contacts_list');
            if (!in_array($iPersonId, $oContactsSet->GetColumnAsArray('contact_id'))) {
                $oLnk = MetaModel::NewObject('lnkContactToTicket');
                $oLnk->Set('contact_id', $iPersonId);
                $oLnk->Set('ticket_id', $this->GetKey());
                $oContactsSet->AddItem($oLnk);
                $this->Set('contacts_list', $oContactsSet);
                $this->DBUpdate();
            }
	      }
		    return true;
	  }

	public function RemoveCurrentUserFromContacts()
	  {
        $iPersonId = UserRights::GetContactId();
        if ($iPersonId > 0) {
            $oContactsSet = $this->Get('contacts_list');
            foreach ($oContactsSet as $oLnk) {
                if ($oLnk->Get('contact_id') == $iPersonId) {
                    $oContactsSet->RemoveItem($oLnk->GetKey());
                    $this->Set('contacts_list', $oContactsSet);
                    $this->DBUpdate();
                    return true;
                }
            }
        }
      return true;
	  }

public function UpdateParentTicketLog()
{
	$oLog = $this->Get('log');
	$sLog = $oLog->GetModifiedEntry('html');
	if ($sLog != '')
	{
		$oTicket = MetaModel::GetObject('Ticket', $this->Get('ticket_id'), false);
		if ($oTicket)
		{
			$oTicket->Set('private_log', $sLog);
			$oTicket->DBUpdate();
		}
	}
}

protected function OnUpdate()
{
	$this->UpdateParentTicketLog();
}

function DisplayBareRelations(WebPage $oPage, $bEditMode = false)
{
	parent::DisplayBareRelations($oPage, $bEditMode);

	$sTicketListAttCode = 'tickets_list';

	if (MetaModel::IsValidAttCode(get_class($this), $sTicketListAttCode))
	{
		// Display one list per leaf class (the only way to display the status as of now)

		$oAttDef = MetaModel::GetAttributeDef(get_class($this), $sTicketListAttCode);
		$sLnkClass = $oAttDef->GetLinkedClass();
		$sExtKeyToMe = $oAttDef->GetExtKeyToMe();
		$sExtKeyToRemote = $oAttDef->GetExtKeyToRemote();

		$iTotal = 0;
		$aSearches = array();

		foreach (MetaModel::EnumChildClasses('Ticket') as $sSubClass)
		{
			if (!MetaModel::HasChildrenClasses($sSubClass))
			{
				$sStateAttCode = MetaModel::GetStateAttributeCode($sSubClass);
				if ($sStateAttCode != '')
				{
				    // Todo: base the search condition on operational_status = 'ongoing' for a more flexible behavior
					$oSearch = DBSearch::FromOQL("SELECT $sSubClass AS t JOIN $sLnkClass AS lnk ON lnk.$sExtKeyToRemote = t.id WHERE lnk.$sExtKeyToMe = :myself AND t.$sStateAttCode NOT IN ('rejected', 'resolved', 'closed') AND lnk.impact_code != 'not_impacted'", array('myself' => $this->GetKey()));
					$aSearches[$sSubClass] = $oSearch;

					$oSet = new DBObjectSet($oSearch);
					$oSet->SetShowObsoleteData(utils::ShowObsoleteData());
					$iTotal += $oSet->Count();
				}
			}
		}

		$sCount = ($iTotal > 0) ? ' ('.$iTotal.')' : '';
		$oPage->SetCurrentTab('Class:FunctionalCI/Tab:OpenedTickets', Dict::S('Class:FunctionalCI/Tab:OpenedTickets').$sCount);

		foreach ($aSearches as $sSubClass => $oSearch)
		{
			$sBlockId = __class__.'_opened_'.$sSubClass;
			$oBlock = new DisplayBlock($oSearch, 'list', false);
			$oBlock->Display($oPage, $sBlockId, array(
			    'menu' => false,
			    'panel_title' => MetaModel::GetName($sSubClass),
			    'panel_icon' => MetaModel::GetClassIcon($sSubClass, false)
			    )
			);
		}
	}
}

	public function GetIcon($bImgTag = true)
	{
	   $sIconClass = 'NetworkDeviceType'; // the class storing the image which will be used as icon for the current object
	   $sExtKeyCode = 'networkdevicetype_id'; // the external key attribute code pointing to the class storing the image attribute
	   $sIconAttCode = 'logo'; // the attribute code of the image in the IconClass

		 $iObj = $this->Get($sExtKeyCode);
		 if ($iObj > 0) {
		    $oObj = MetaModel::GetObject($sIconClass, $iObj, true, true);
        $oImage = $oObj->Get($sIconAttCode);
    		$sIconUrl = $oImage->IsEmpty() ? '' : $oImage->GetDisplayURL($sIconClass, $iObj, $sIconAttCode);
    		if (strlen($sIconUrl) > 0) {
    			 if ($bImgTag) {
    				  return "<img src=\"$sIconUrl\" alt=''/>";
    			 } else {
    				  return $sIconUrl;
    			 }
    		}
		 }
		 // Return the default image
	   return parent::GetIcon($bImgTag);
	}

	public function GetIcon($bImgTag = true)
	{
	   // If there is an image defined on the associated Software, we use it
	   $sIconClass = 'Software'; // the class storing the image which will be used as icon for the current object
	   $sExtKeyCode = 'software_id'; // the attribute code pointing to the class having the image to display
	   $sIconAttCode = 'logo'; // the attribute code of the image to display on the IconClass

		 $iObj = $this->Get($sExtKeyCode);
		 if ($iObj > 0) {
		    $oObj = MetaModel::GetObject($sIconClass, $iObj, true, true);
        $oImage = $oObj->Get($sIconAttCode);
    		$sIconUrl = $oImage->IsEmpty() ? '' : $oImage->GetDisplayURL($sIconClass, $iObj, $sIconAttCode);
    		if (strlen($sIconUrl) > 0) {
    			 if ($bImgTag) {
    				  return "<img src=\"$sIconUrl\" alt=''/>";
    			 } else {
    				  return $sIconUrl;
    			 }
    		}
		 }
		 // Return the default image
	   return parent::GetIcon($bImgTag);
	}

	function DisplayBareRelations(WebPage $oPage, $bEditMode = false)
	{
		parent::DisplayBareRelations($oPage, $bEditMode);

      $bIsCreation = ($this->GetKey() != -1)? false : true;
      if (!$bIsCreation)	{
        $oPage->SetCurrentTab('Class:Subnet/Tab:IPUsage');

        $bit_ip = ip2long($this->Get('ip'));
        $bit_mask = ip2long($this->Get('ip_mask'));

        $iIPMin = sprintf('%u', ($bit_ip & $bit_mask) | 1); // exclude the first one: identifies the subnet itself
        $iIPMax = sprintf('%u', (($bit_ip | (~$bit_mask))) & 0xfffffffe); // exclude the last one : broadcast address

        $sIPMin = long2ip($iIPMin);
        $sIPMax = long2ip($iIPMax);

        $oPage->p(Dict::Format('Class:Subnet/Tab:IPUsage-explain', $sIPMin, $sIPMax));

        $oIfFilter = DBObjectSearch::FromOQL("SELECT IPInterface AS if WHERE INET_ATON(if.ipaddress) >= INET_ATON('$sIPMin') AND INET_ATON(if.ipaddress) <= INET_ATON('$sIPMax')");
        $oIfSet = new CMDBObjectSet($oIfFilter);
        $oBlock = new DisplayBlock($oIfFilter, 'list', false);
        $oBlock->Display($oPage, 'nwif', array(
            'menu' => false,
            'panel_title' => MetaModel::GetName('IPInterface'),
				    'panel_icon' => MetaModel::GetClassIcon('IPInterface', false)
            )
        );

        $iCountUsed = $oIfSet->Count();
        $iCountRange = $iIPMax - $iIPMin; // On 32-bit systems the substraction will be computed using floats for values greater than PHP_MAX_INT;
        $iFreeCount =  $iCountRange - $iCountUsed;

        $oPage->SetCurrentTab('Class:Subnet/Tab:FreeIPs');
        $oPage->p(Dict::Format('Class:Subnet/Tab:FreeIPs-count', $iFreeCount));
        $oPage->p(Dict::S('Class:Subnet/Tab:FreeIPs-explain'));

        $aUsedIPs = $oIfSet->GetColumnAsArray('ipaddress', false);
        $iAnIP = $iIPMin;
        $iFound = 0;
        while (($iFound < min($iFreeCount, 10)) && ($iAnIP <= $iIPMax))
        {
          $sAnIP = long2ip($iAnIP);
          if (!in_array($sAnIP, $aUsedIPs))
          {
            $iFound++;
            $oPage->p($sAnIP);
          }
          $iAnIP++;
        }
			}
	}

protected function AddConnectedNetworkDevice()
{
	$oDevice = MetaModel::GetObject('ConnectableCI', $this->Get('connectableci_id'));
	if (is_object($oDevice) && (get_class($oDevice) == 'NetworkDevice'))
	{
		$sOQL = "SELECT  lnkConnectableCIToNetworkDevice WHERE connectableci_id = :device AND networkdevice_id = :network AND network_port = :nwport AND device_port = :devport";
		$oConnectionSet = new DBObjectSet(DBObjectSearch::FromOQL($sOQL),
						array(),
						array(
							'network' => $this->Get('connectableci_id'),
							'device' => $this->Get('networkdevice_id'),
							'devport' => $this->Get('network_port'),
							'nwport' => $this->Get('device_port'),
							)
		);
		if ($oConnectionSet->Count() == 0)
		{
			$sLink = $this->Get('connection_type');
			$sConnLink = ($sLink == 'uplink') ? 'downlink' : 'uplink';

			$oNewLink = new lnkConnectableCIToNetworkDevice();
			$oNewLink->Set('networkdevice_id', $this->Get('connectableci_id'));
			$oNewLink->Set('connectableci_id', $this->Get('networkdevice_id'));
			$oNewLink->Set('network_port', $this->Get('device_port'));
			$oNewLink->Set('device_port', $this->Get('network_port'));
			$oNewLink->Set('connection_type', $sConnLink);
			$oNewLink->DBInsert();
		}
	}
}

	protected function UpdateConnectedNetworkDevice()
	{
	  $aFields = array('networkdevice_id','connectableci_id','network_port','device_port','connection_type');
    $aChanges = $this->ListPreviousValuesForUpdatedAttributes();
    $aPrev = array(); // Previous values of the current link object before it was modified
    foreach ($aFields as $sFieldCode) {
        $aPrev[$sFieldCode] = array_key_exists($sFieldCode, $aChanges) ? $aChanges[$sFieldCode] : $this->Get($sFieldCode);
    }
		$sPrevLink = ($aPrev['connection_type'] == 'uplink') ? 'downlink' : 'uplink';
		$sConnLink = ($this->Get('connection_type') == 'uplink') ? 'downlink' : 'uplink';

    $oNewDevice = MetaModel::GetObject('ConnectableCI', $this->Get('connectableci_id'), false);
    $oPrevDevice = MetaModel::GetObject('ConnectableCI', $aPrev['connectableci_id'], false);
    $bNew = (is_object($oNewDevice) && (get_class($oNewDevice) == 'NetworkDevice'));
    $bPrev = (is_object($oPrevDevice) && (get_class($oPrevDevice) == 'NetworkDevice'));
		$sOQL = "SELECT  lnkConnectableCIToNetworkDevice WHERE connectableci_id = :device AND networkdevice_id = :network AND network_port = :nwport AND device_port = :devport AND connection_type = :link";

    if ($bPrev) { // There was a twin
      // Retrieve twin link using previous values of the current link
			$oConnectionSet = new DBObjectSet(DBObjectSearch::FromOQL($sOQL),
							array(),
							array(
								'network' => $aPrev['connectableci_id'],
								'device' => $aPrev['networkdevice_id'],
								'devport' => $aPrev['network_port'],
								'nwport' => $aPrev['device_port'],
								'link' => $sPrevLink,
								)
			);
			if ($bNew) { // and a twin must still exist, so update the existing
			  while ($oConnection = $oConnectionSet->Fetch()) {
				    $oConnection->Set('networkdevice_id', $this->Get('connectableci_id'));
				    $oConnection->Set('connectableci_id', $this->Get('networkdevice_id'));
				    $oConnection->Set('network_port', $this->Get('device_port'));
				    $oConnection->Set('device_port', $this->Get('network_port'));
				    $oConnection->Set('connection_type',$sConnLink);
				    $oConnection->DBUpdate();
			  }
			}
			else {  // and no twin is needed anymore, so delete the existing
			  while ($oConnection = $oConnectionSet->Fetch()) {
				    $oConnection->DBDelete();
			  }
			}
		}
		elseif ($bNew) { // There was no twin but a twin must exist now
      // Search for a twin link using current values inverted
			$oConnectionSet = new DBObjectSet(DBObjectSearch::FromOQL($sOQL),
							array(),
							array(
								'network' => $this->Get('connectableci_id'),
								'device' => $this->Get('networkdevice_id'),
								'devport' => $this->Get('device_port'),
								'nwport' => $this->Get('network_port'),
								'link' => $sConnLink,
								)
			);
			if ($oConnectionSet->Count() == 0) {
				$oNewLink = new lnkConnectableCIToNetworkDevice();
				$oNewLink->Set('networkdevice_id', $this->Get('connectableci_id'));
				$oNewLink->Set('connectableci_id', $this->Get('networkdevice_id'));
				$oNewLink->Set('network_port', $this->Get('device_port'));
				$oNewLink->Set('device_port', $this->Get('network_port'));
				$oNewLink->Set('connection_type', $sConnLink);
				$oNewLink->DBInsert();
			}
		}
	}

protected function DeleteConnectedNetworkDevice()
{
	// The device might be already deleted (reentrance in the current procedure when both device are NETWORK devices!)
	$oDevice = MetaModel::GetObject('ConnectableCI', $this->Get('connectableci_id'), false);
	if (is_object($oDevice) && (get_class($oDevice) == 'NetworkDevice'))
	{
		// Track and delete the counterpart link
		$sOQL = "SELECT  lnkConnectableCIToNetworkDevice WHERE connectableci_id = :device AND networkdevice_id = :network AND network_port = :nwport AND device_port = :devport";
		$oConnectionSet = new DBObjectSet(DBObjectSearch::FromOQL($sOQL),
						array(),
						array(
							'network' => $this->Get('connectableci_id'),
							'device' => $this->Get('networkdevice_id'),
							'devport' => $this->Get('network_port'),
							'nwport' => $this->Get('device_port'),
							)
		);
		// There should be one link - do it in a safe manner anyway
		while ($oConnection = $oConnectionSet->Fetch())
		{
			$oConnection->DBDelete();
		}
	}
}

protected function AfterInsert()
{
	$this->AddConnectedNetworkDevice();
	parent::AfterInsert();
}

protected function AfterUpdate()
{
	$this->UpdateConnectedNetworkDevice();
	parent::AfterUpdate();
}

protected function AfterDelete()
{
	$this->DeleteConnectedNetworkDevice();
	parent::AfterDelete();
}

