    $aChanges = $this->ListChanges();
    if (array_key_exists('client_id', $aChanges) || array_key_exists('client_secret', $aChanges) || array_key_exists('redirect_url', $aChanges)) {
        $sMessage = Dict::S('itop-oauth-client:Message:RegenerateToken');
