            } else {
                $oPage->SetCurrentTab($sTabCode, Dict::S($sTabCode), Dict::S($sTabCode."+"));
            }
            self::DisplaySet($oPage, $oKnownErrorSet, [
              'menu' => false,
              'panel_title' => Dict::S($sTabCode),
              'panel_icon' => MetaModel::GetClassIcon($sKnownErrorClass, false),
              'panel_title_tooltip' => Dict::S($sTabCode."+"),
            ]);
        }
	}

public function ResolveChildTickets()
{
	static $aTickets = array(); // prevent infinite recursion

	// Automatically resolve child requests
	$sOQL = "SELECT UserRequest WHERE parent_request_id = :ticket AND status != 'resolved'";
	$oChildRequestSet = new DBObjectSet(DBObjectSearch::FromOQL($sOQL), array(), array('ticket' => $this->GetKey()));
	while($oRequest = $oChildRequestSet->Fetch())
	{
		if (!array_key_exists($oRequest->GetKey(), $aTickets))
		{
			$aTickets[$oRequest->GetKey()] = true;
			$oRequest->ResolveFrom($this);
		}
	}
	return true;
}

	public function ResolveFrom($oParentTicket)
	{
		if ($this->Get('status') != 'resolved' && $this->Get('status') != 'closed' )
		{
			$aDummy = array();
			$aExcludedAttributes = array('team_id', 'agent_id');
		    foreach(MetaModel::ListAttributeDefs(get_class($this)) as $sAttCode => $oAttDef)
		    {
		    	// Exclude inter dependant attributes to keep consistency
		    	if(in_array($sAttCode, $aExcludedAttributes))
		    	{
		    		continue;
		    	}

		         if (($this->GetAttributeFlags($sAttCode, $aDummy, 'resolved') & OPT_ATT_MANDATORY) && empty($this->Get($sAttCode)))
		         {
		            $this->Set($sAttCode, $oParentTicket->Get($sAttCode));
		         }
		    }
		  if (($this->Get('team_id') == 0) || ($this->Get('agent_id') ==0))  
           {  
                  $this->Set('team_id', $oParentTicket->Get('team_id'));
                  $this->Set('agent_id', $oParentTicket->Get('agent_id'));
           }
			$sParent = '[['.get_class($oParentTicket).':'.$oParentTicket->GetKey().'|'.$oParentTicket->Get('ref').']]';
			$this->Set('solution', Dict::Format('Tickets:ResolvedFrom', $sParent, MetaModel::GetName(get_class($oParentTicket))));
			$this->ApplyStimulus('ev_autoresolve');
			$this->DBUpdate();
		}
	}

public function UpdateChildRequestLog()
{
	$oLog = $this->Get('public_log');
	$sLogPublic = $oLog->GetModifiedEntry('html');
	if ($sLogPublic != '')
	{
		$sOQL = "SELECT UserRequest WHERE parent_request_id=:ticket";
		$oChildRequestSet = new DBObjectSet(DBObjectSearch::FromOQL($sOQL),
						array(),
						array(
							'ticket' => $this->GetKey(),
							)
						);
		while($oRequest = $oChildRequestSet->Fetch())
		{
			$oRequest->set('public_log',$sLogPublic);
			$oRequest->DBUpdate();
		}

	}
	$oLog = $this->Get('private_log');
	$sLogPrivate = $oLog->GetModifiedEntry('html');
	if ($sLogPrivate != '')
	{
		$sOQL = "SELECT UserRequest WHERE parent_request_id=:ticket";
		$oChildRequestSet = new DBObjectSet(DBObjectSearch::FromOQL($sOQL),
						array(),
						array(
							'ticket' => $this->GetKey(),
							)
						);
		while($oRequest = $oChildRequestSet->Fetch())
		{
			$oRequest->set('private_log',$sLogPrivate);
			$oRequest->DBUpdate();
		}
	}
	return true;

}

    public function ComputeImpactedItems()
	{
        // This method is kept for backward compatibility
        // in case a delta redefines it, but you may call
        // UpdateImpactedItems directly
		$this->UpdateImpactedItems();
	}

    protected function OnInsert()
	{
      parent::OnInsert();
      $this->SetIfNull('last_update', time());
      $this->SetIfNull('start_date', time());
	}

   	protected function OnUpdate()
	{
    parent::OnUpdate();
		$this->Set('last_update', time());
		$this->UpdateChildRequestLog();
	}

public function PrefillSearchForm(&$aContextParam)
{
  if($aContextParam['dest_class'] == 'Service' || is_subclass_of($aContextParam['dest_class'], 'Service'))
  {
    if(MetaModel::IsValidAttCode($aContextParam['dest_class'],'org_id') && !empty($aContextParam['source_obj']->Get('provider_id')))
    {
        $aContextParam['filter']->ResetCondition();
        $aContextParam['filter']->AddCondition('org_id', $aContextParam['source_obj']->Get('provider_id'));
    }
  }
  elseif (($aContextParam['dest_class'] == 'Contact' || is_subclass_of($aContextParam['dest_class'], 'Contact'))
          || ($aContextParam['dest_class'] == 'Document' || is_subclass_of($aContextParam['dest_class'], 'Document')))
  {
    if(MetaModel::IsValidAttCode($aContextParam['dest_class'],'org_id') && !empty($aContextParam['source_obj']->Get('provider_id')) && !empty($aContextParam['source_obj']->Get('org_id')))
    {
      $aContextParam['filter']->ResetCondition();
      $aOrgIds = array( $aContextParam['source_obj']->Get('provider_id'),
                        $aContextParam['source_obj']->Get('org_id'));
      $aContextParam['filter']->AddCondition('org_id', $aOrgIds , 'IN');
    }
  }
}

   	public function GetAttributeFlags($sAttCode, &$aReasons = array(), $sTargetState = '')
	{
		// This function is invoked when the object is EDITED on the Console
		// It is called for each and every field of the object,
		// but we just want to change the behavior for a single field
		if ($sAttCode == 'use_count' || $sAttCode == 'last_use_date')
		{
			// Combine the new Flag with those impose by a parent class
			return(OPT_ATT_READONLY | parent::GetAttributeFlags($sAttCode, $aReasons, $sTargetState));
		}
		return parent::GetAttributeFlags($sAttCode, $aReasons, $sTargetState);
	}

   	public function GetInitialStateAttributeFlags($sAttCode, &$aReasons = array())
{
    // This function is invoked when the object is CREATED on the Console
    // It is called for each and every field of the object,
    // but we just want to change the behavior for a single field
		if ($sAttCode == 'use_count' || $sAttCode == 'last_use_date')
    {
        // Combine the new Flag with those imposed by a parent class
        return(OPT_ATT_READONLY | parent::GetInitialStateAttributeFlags($sAttCode, $aReasons));
    }
    // For other fields ask the parent class to do the job
    return parent::GetInitialStateAttributeFlags($sAttCode, $aReasons);
}

public function CanBeImpersonated(): bool
{
	return false;
}

public static function GetTicketRefFormat()
{
        return 'C-%06d';
}

    protected function OnInsert()
	{
    parent::OnInsert();
		$this->SetIfNull('creation_date', time());
		$this->SetIfNull('last_update', time());
	}

    protected function OnUpdate()
	{
    parent::OnUpdate();
		$this->Set('last_update', time());
	}

